// The SDK against the contracts' checked-in vectors (contracts/tests/vectors/*.json, generated by
// `cargo test -p fumpad-tests vectors`): attestation messages, keeper signatures, Ed25519 instruction data,
// consumed / position / ticket PDAs, and the exact DBC create_config instruction data.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { Keypair, PublicKey } from "@solana/web3.js";
import { describe, expect, it } from "vitest";

import {
  bytesToHex,
  consumedRebuyPda,
  consumedSellPda,
  dbcCreateConfigIx,
  ed25519InstructionData,
  encodeRebuyMessage,
  encodeSellMessage,
  FUMPAD_PROGRAM_ID,
  fumpadConfigParams,
  hexToBytes,
  positionPda,
  signAttestation,
  ticketPda,
} from "../src/index.js";

const dir = join(dirname(fileURLToPath(import.meta.url)), "../../../contracts/tests/vectors");
const A = JSON.parse(readFileSync(join(dir, "attestation.json"), "utf8"));
const D = JSON.parse(readFileSync(join(dir, "dbc_config.json"), "utf8"));
const bytes = (h: string) => Uint8Array.from(hexToBytes(h));
const seeds: Map<string, Uint8Array> = new Map(A.keepers.map((k: { pubkey: string; seed_hex: string }) => [k.pubkey, bytes(k.seed_hex)]));

describe("contracts/tests/vectors/attestation.json", () => {
  it("program id", () => expect(A.program_id).toBe(FUMPAD_PROGRAM_ID.toBase58()));
  it("keeper seeds → pubkeys", () => {
    for (const [pk, seed] of seeds) expect(Keypair.fromSeed(seed).publicKey.toBase58()).toBe(pk);
  });
  for (const v of A.sells) {
    it(`sell ${v.name}: message, signatures, Ed25519 data, PDAs`, () => {
      const r = v.record;
      const sig = bytes(r.signature_hex);
      const m = encodeSellMessage({
        programId: new PublicKey(r.program_id),
        clusterTag: r.cluster_tag,
        mint: new PublicKey(r.mint),
        pool: new PublicKey(r.pool),
        venue: r.venue,
        signature: sig,
        ixKey: r.ix_key,
        trader: new PublicKey(r.trader),
        baseAmount: BigInt(r.base_amount),
        quoteGross: BigInt(r.quote_gross),
        ticketTokens: BigInt(r.ticket_tokens),
        ticketPriceQ64: BigInt(r.ticket_price_q64),
        usdCents: BigInt(r.usd_cents),
        pythPublishTime: BigInt(r.pyth_publish_time),
        slot: BigInt(r.slot),
        blockTime: BigInt(r.block_time),
      });
      expect(m.length).toBe(v.message_len);
      expect(bytesToHex(m)).toBe(v.message_hex);
      const sigs = v.signatures.map((s: { keeper: string; signature_hex: string }) => {
        expect(bytesToHex(signAttestation(m, seeds.get(s.keeper)!))).toBe(s.signature_hex);
        return { keeper: new PublicKey(s.keeper), signature: bytes(s.signature_hex) };
      });
      expect(bytesToHex(ed25519InstructionData(m, sigs))).toBe(v.ed25519_ix_data_hex);
      expect(consumedSellPda(sig, r.ix_key).toBase58()).toBe(v.consumed_pda);
      expect(positionPda(new PublicKey(r.mint), new PublicKey(r.trader)).toBase58()).toBe(v.position_pda);
      expect(ticketPda(new PublicKey(r.mint), new PublicKey(r.trader), 0n).toBase58()).toBe(v.ticket_pda_seq0);
    });
  }
  for (const v of A.rebuys) {
    it(`rebuy ${v.name}: message, signatures, Ed25519 data, consumed PDA`, () => {
      const r = v.record;
      const sig = bytes(r.signature_hex);
      const m = encodeRebuyMessage({
        programId: new PublicKey(r.program_id),
        clusterTag: r.cluster_tag,
        mint: new PublicKey(r.mint),
        ticket: new PublicKey(r.ticket),
        owner: new PublicKey(r.owner),
        signature: sig,
        ixKey: r.ix_key,
        debitTokens: BigInt(r.debit_tokens),
        slot: BigInt(r.slot),
        blockTime: BigInt(r.block_time),
      });
      expect(bytesToHex(m)).toBe(v.message_hex);
      const sigs = v.signatures.map((s: { keeper: string; signature_hex: string }) => ({ keeper: new PublicKey(s.keeper), signature: bytes(s.signature_hex) }));
      expect(bytesToHex(ed25519InstructionData(m, sigs))).toBe(v.ed25519_ix_data_hex);
      expect(consumedRebuyPda(sig, r.ix_key, new PublicKey(r.ticket)).toBase58()).toBe(v.consumed_pda);
    });
  }
});

describe("contracts/tests/vectors/dbc_config.json", () => {
  for (const net of ["mainnet", "devnet"] as const) {
    it(`${net}: create_config data is byte-identical`, () => {
      const ix = dbcCreateConfigIx({ config: Keypair.generate().publicKey, payer: Keypair.generate().publicKey, params: fumpadConfigParams(net) });
      expect(bytesToHex(ix.data)).toBe(D[net].create_config_data_hex);
      expect(ix.keys[1].pubkey.toBase58()).toBe(D.fee_claimer);
      expect(ix.keys[2].pubkey.toBase58()).toBe(D.leftover_receiver);
    });
  }
});
